From 9db7595a83420f029dd52a462d766d4ac585e9c7 Mon Sep 17 00:00:00 2001
From: Holger Schemel <info@artsoft.org>
Date: Thu, 7 Feb 2019 23:40:30 +0100
Subject: [PATCH] fixed bug when snapping envelope (introduced by commit
 931d95b5)


diff --git a/src/events.c b/src/events.c
index 31d45abf..ee5e492c 100644
--- a/src/events.c
+++ b/src/events.c
@@ -405,7 +405,10 @@ void ClearPlayerAction(void)
   // simulate key release events for still pressed keys
   key_joystick_mapping = 0;
   for (i = 0; i < MAX_PLAYERS; i++)
+  {
     stored_player[i].action = 0;
+    stored_player[i].snap_action = 0;
+  }

   ClearJoystickState();
   ClearPlayerMouseAction();
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was likely caused by not properly resetting the `snap_action` property of the `stored_player` structure when clearing player actions, which can lead to inconsistent states when snapping envelopes. This inconsistency would manifest when the previous `snap_action` state was retained, potentially affecting gameplay or functionality that relies on the proper clearing of player actions.

        Commit message:
        fixed bug when snapping envelope (introduced by commit
 931d95b5)  

        Patch:

 void ClearPlayerAction(void)
 {
   int i;

   // simulate key release events for still pressed keys
   key_joystick_mapping = 0;
   for (i = 0; i < MAX_PLAYERS; i++)
+  {
     stored_player[i].action = 0;
+    stored_player[i].snap_action = 0;
+  }

   ClearJoystickState();
   ClearPlayerMouseAction();
 }



